@push('scripts')<script>(() => { const form = document.querySelector('[data-availability-form]'); if (!form) return; const checkIn = form.querySelector('#check_in'), checkOut = form.querySelector('#check_out'); const error = (el, msg) => { el.setAttribute('aria-invalid', 'true'); form.querySelector(`[data-error-for="${el.name}"]`).textContent = msg; }; const clear = el => { el.removeAttribute('aria-invalid'); form.querySelector(`[data-error-for="${el.name}"]`).textContent = ''; }; checkIn.addEventListener('change', () => { clear(checkIn); if (!checkIn.value) return; const date = new Date(`${checkIn.value}T00:00:00`); date.setDate(date.getDate() + 1); checkOut.min = date.toISOString().slice(0, 10); if (checkOut.value <= checkIn.value) checkOut.value = ''; }); form.addEventListener('submit', event => { let valid = true; if (!checkIn.value) { error(checkIn, 'Vui lòng chọn ngày nhận phòng.'); valid = false; } else clear(checkIn); if (!checkOut.value) { error(checkOut, 'Vui lòng chọn ngày trả phòng.'); valid = false; } else if (checkOut.value <= checkIn.value) { error(checkOut, 'Ngày trả phòng phải sau ngày nhận phòng.'); valid = false; } else clear(checkOut); if (!valid) event.preventDefault(); }); })();</script>@endpush
